using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class AEQuality {
 public static object Run(){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit required");string r=Path.GetFullPath(Path.Combine(Application.dataPath,"../../..")),h=r+"/SourceAssets/F1_AbandonedCamouflage/",o=r+"/Docs/Review/2026-11-12_1F_Abandoned/";var errors=new List<string>();var rows=new List<object>();long bytes=0;var assets=new List<object>();foreach(string file in new[]{"models_environment.json"})foreach(var q in JObject.Parse(File.ReadAllText(h+file))){string path=(string)q.Value["asset"];bytes+=new FileInfo(Path.GetFullPath(Path.Combine(Application.dataPath,"..",path))).Length;var meshes=AssetDatabase.LoadAllAssetsAtPath(path).OfType<Mesh>().OrderBy(m=>m.name).ToArray();var importer=(ModelImporter)AssetImporter.GetAtPath(path);if(importer.isReadable)errors.Add("Readable "+path);foreach(var m in meshes){var vs=m.vertices;var ns=m.normals;var ts=m.triangles;int nonFinite=vs.Count(v=>!float.IsFinite(v.x)||!float.IsFinite(v.y)||!float.IsFinite(v.z)),zero=0,reversed=0;for(int i=0;i<ts.Length;i+=3){var cross=Vector3.Cross(vs[ts[i+1]]-vs[ts[i]],vs[ts[i+2]]-vs[ts[i]]);if(cross.sqrMagnitude<1e-24f)zero++;else if(ns.Length==vs.Length&&Vector3.Dot(cross.normalized,(ns[ts[i]]+ns[ts[i+1]]+ns[ts[i+2]]).normalized)<-.5f)reversed++;}rows.Add(new{name=m.name,vertices=vs.Length,triangles=ts.Length/3,nonFinite,zeroArea=zero,reversedNormals=reversed});if(nonFinite!=0||zero!=0||reversed!=0)errors.Add(m.name+" zero="+zero+" reversed="+reversed);}
 assets.Add(new{path,triangles=meshes.Select(m=>m.triangles.Length/3).ToArray(),materials=AssetDatabase.LoadAssetAtPath<GameObject>(path).GetComponentsInChildren<Renderer>().SelectMany(v=>v.sharedMaterials).Select(AssetDatabase.GetAssetPath).Distinct().ToArray()});}
  var root=GameObject.Find("1F_AbandonedFactory");foreach(var g in root.GetComponentsInChildren<LODGroup>()){var ls=g.GetLODs();if(ls.Any(l=>l.renderers.Length==0||l.renderers.Any(x=>!x)))errors.Add("Invalid LOD "+g.name);}
  var result=new{models=assets.Count,meshCount=rows.Count,modelBytes=bytes,errors,meshes=rows,assets};File.WriteAllText(o+"quality.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{result.models,result.meshCount,result.modelBytes,errors};
 }
}
